// Author: MiYu. DotA rune storage and release exercise real source scripts and unit effects.
#include "session.h"
#include "setup.h"
#include <array>
#include <bit>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc!=4)throw std::runtime_error("Usage: war3_dota_rune_tests <data-root> <dota-map> <regen|damage|illusion|wand|wand-charge>");std::wstring mode=argv[3];const char* rune=mode==L"regen"?"I008":mode==L"damage"?"I00K":mode==L"illusion"?"I007":nullptr;if(!rune && mode!=L"wand" && mode!=L"wand-charge")throw std::runtime_error("Unknown rune mode");Archives archives(argv[1]);archives.mountMap(argv[2]);ObjectData definitions(archives);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto data=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(data->bytes);ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));session.attachWorld(std::move(world));session.audioSimulationClock();session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto code=[&](const char* value){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(value)));};auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto player=session.localPlayer().value_or(0);auto hero=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+player),code("Hpal"),real(-4000),real(0),real(0)});require(hero.bits && session.units().contains(hero.bits),"Hero creation failed");auto u=session.units().at(hero.bits);u->acquireRange={};u->healthRegen=0;u->manaRegen=0;u->life=jass::Real::fromInteger(200);u->mana={};vm.invoke("FogEnable",std::array{vm.boolean(false)});vm.invoke("FogMaskEnable",std::array{vm.boolean(false)});if(mode==L"wand-charge"){u->maxLife=u->maxMana=jass::Real::fromInteger(1000);u->healthRegen=u->manaRegen=0;u->regenType="none";auto wand=vm.invoke("UnitAddItemById",std::array{hero,code("I0HB")});require(wand.bits && session.items().contains(wand.bits) && session.items().at(wand.bits)->charges==0,"Uncharged Magic Wand missing");auto enemy=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100006),code("Hpal"),real(-3900),real(0),real(0)});require(enemy.bits && session.units().contains(enemy.bits),"Enemy hero missing");auto enemyState=session.units().at(enemy.bits);enemyState->acquireRange={};enemyState->mana=enemyState->maxMana=jass::Real::fromInteger(1000);require(vm.invoke("UnitAddAbility",std::array{enemy,code("AHds")}).bits && session.castSpell(enemy.bits,ObjectData::code("AHds")),"Enemy self spell rejected");session.advance(2);require(session.items().at(wand.bits)->charges==1,"Enemy cast did not charge Magic Wand");auto castAt=[&](unsigned owner,int x){auto caster=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),code("Hpal"),real(x),real(0),real(0)});require(caster.bits && session.units().contains(caster.bits),"Second caster missing");auto state=session.units().at(caster.bits);state->acquireRange={};state->mana=state->maxMana=jass::Real::fromInteger(1000);require(vm.invoke("UnitAddAbility",std::array{caster,code("AHds")}).bits && session.castSpell(caster.bits,ObjectData::code("AHds")),"Second caster spell rejected");session.advance(2);};castAt(6,-2500);require(session.items().at(wand.bits)->charges==1,"Remote enemy charged Magic Wand");castAt(player,-3900);require(session.items().at(wand.bits)->charges==1,"Ally cast charged Magic Wand");u->life=jass::Real::fromInteger(300);u->mana=jass::Real::fromInteger(100);require(session.useItem(hero.bits,wand.bits),"Naturally charged Magic Wand use rejected");session.advance(1);require(number(u->life)>314.9f && number(u->life)<315.1f && number(u->mana)>114.9f && number(u->mana)<117.f && session.items().at(wand.bits)->charges==0,"Natural Magic Wand charge did not restore resources");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS enemy_spell_charge_and_magic_wand_use\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}if(mode==L"wand"){u->maxLife=u->maxMana=jass::Real::fromInteger(1000);u->life=jass::Real::fromInteger(300);u->mana=jass::Real::fromInteger(100);u->regenType="none";auto wand=vm.invoke("UnitAddItemById",std::array{hero,code("I0HB")});require(wand.bits && session.items().contains(wand.bits),"Magic Wand missing");u->life=jass::Real::fromInteger(300);u->mana=jass::Real::fromInteger(100);vm.invoke("SetItemCharges",std::array{wand,vm.integer(5)});require(session.useItem(hero.bits,wand.bits),"Magic Wand use rejected");session.advance(1);std::cout<<"wand life="<<number(u->life)<<" mana="<<number(u->mana)<<" charges="<<session.items().at(wand.bits)->charges<<" uses="<<definitions.number(ObjectData::code("I0HB"),"ItemData","uses")<<" perishable="<<definitions.number(ObjectData::code("I0HB"),"ItemData","perishable")<<"\n";require(number(u->life)>374.9f && number(u->life)<375.1f && number(u->mana)>174.9f && number(u->mana)<177.f,"Magic Wand did not restore 15 per charge");require(session.items().contains(wand.bits) && session.items().at(wand.bits)->charges==0 && session.itemCooldown(hero.bits,wand.bits)>0,"Magic Wand did not consume script charges or start cooldown");require(!session.useItem(hero.bits,wand.bits),"Magic Wand cooldown did not block use");session.advance(18);u->life=jass::Real::fromInteger(300);u->mana=jass::Real::fromInteger(100);vm.invoke("SetItemCharges",std::array{wand,vm.integer(1)});require(session.useItem(hero.bits,wand.bits),"Single-charge Magic Wand use rejected");session.advance(1);require(number(u->life)>314.9f && number(u->life)<315.1f && number(u->mana)>114.9f && number(u->mana)<117.f && session.items().at(wand.bits)->charges==0,"Single-charge Magic Wand did not restore 15");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS magic_wand_charge_restoration\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}auto ground=vm.invoke("CreateItem",std::array{code(rune),real(-3900),real(0)});auto bottle=vm.invoke("UnitAddItemById",std::array{hero,code("I0AM")});require(ground.bits && bottle.bits && session.useItem(hero.bits,bottle.bits,ground.bits),"Bottle could not target rune");for(int i=0;i<4;++i)session.advance(.25);require(!session.items().contains(ground.bits),"Rune remained after storage");std::uint32_t stored=0;for(auto id:u->inventory)if(id && session.items().contains(id))stored=id;require(stored && stored!=bottle.bits,"Stored rune bottle missing");auto initial=session.unitCombatDisplay(hero.bits);require(initial.has_value(),"Hero combat display missing");auto minimum=initial->weapons[0].minimum;require(session.useItem(hero.bits,stored),"Stored rune use rejected");for(int i=0;i<4;++i)session.advance(.25);bool refilled=false;for(auto id:u->inventory)if(id && session.items().contains(id) && session.items().at(id)->type==ObjectData::code("I0AP"))refilled=true;require(refilled,"Bottle did not refill after rune use");for(auto& [id,item]:session.items())require(item->type!=ObjectData::code(rune) || item->holder,"Released rune remained on the ground");
        if(mode==L"regen")require(number(u->life)>290 && number(u->mana)>50,"Regeneration rune did not restore health and mana");else if(mode==L"damage"){auto combat=session.unitCombatDisplay(hero.bits);require(combat && combat->weapons[0].minimum>minimum && u->spellBonus(&UnitBuff::damageBonus)>.99f,"Damage rune did not affect weapon damage");}else{unsigned count=0;for(auto& [id,unit]:session.units())if(unit->illusion && unit->illusionOriginal==hero.bits){++count;require(unit->damageDealt==.35f && unit->damageTaken==2.f && unit->timedLife && unit->timedLife->duration==75,"Rune illusion source parameters differ");}require(count==2,"Illusion rune did not create two illusions");}require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS rune_storage_release_and_effect\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
